import java.util.TreeSet;

public class Solution {
    public static int[] solve(int[] reservations, int[] queries) {
        // 예약 시각을 TreeSet에 넣으면 입력 순서와 관계없이 작은 순서로 정렬되고 같은 시각은 하나로 합쳐진다.
        TreeSet<Integer> times = new TreeSet<>();
        for (int time : reservations) {
            times.add(time);
        }

        int[] answer = new int[queries.length];
        for (int index = 0; index < queries.length; index++) {
            int query = queries[index];
            // floor는 질의 시각과 같거나 이른 마지막 예약이고 ceiling은 같거나 늦은 첫 예약이다.
            // 가장 가까운 예약은 반드시 이 두 후보 중 하나이므로 트리 높이만큼만 내려가서 찾는다.
            Integer before = times.floor(query);
            Integer after = times.ceiling(query);
            if (before == null && after == null) {
                answer[index] = -1;
            } else if (before == null) {
                answer[index] = after;
            } else if (after == null) {
                answer[index] = before;
            } else {
                // 거리가 같으면 이른 예약을 고르므로 before가 이기는 조건에 등호를 넣는다.
                answer[index] = query - before <= after - query ? before : after;
            }
        }
        return answer;
    }
}

