import java.util.Arrays;

public class Solution {
    // 아직 닿지 않은 정점의 거리입니다. 반환 배열에서도 같은 값으로 알립니다.
    static final long INF = Long.MAX_VALUE;

    public static long[] solve(int n, int[][] edges, int start) {
        long[] distance = new long[n];
        Arrays.fill(distance, INF);
        distance[start] = 0;

        // 음수 사이클이 없으면 최단 길은 간선을 최대 n - 1개 지나므로 n - 1번 완화하면 충분하다.
        for (int round = 1; round <= n - 1; round++) {
            boolean changed = false;
            for (int[] edge : edges) {
                int from = edge[0];
                int to = edge[1];
                int cost = edge[2];
                // 닿지 않은 정점에서 나가는 간선을 완화하면 INF에 비용을 더해 가짜 거리가 생긴다.
                if (distance[from] == INF) continue;
                // 거리 합은 int 범위를 넘을 수 있으므로 long으로 더한다.
                if (distance[from] + cost < distance[to]) {
                    distance[to] = distance[from] + cost;
                    changed = true;
                }
            }
            if (!changed) break;
        }

        // n - 1번 뒤에도 줄어드는 거리가 있으면 출발점에서 닿는 음수 사이클이 있다.
        for (int[] edge : edges) {
            int from = edge[0];
            if (distance[from] == INF) continue;
            if (distance[from] + edge[2] < distance[edge[1]]) {
                return new long[0];
            }
        }
        return distance;
    }
}

