public class Solution {
    public static int[] solve(int[] scores, int[][] ranges) {
        int[] answer = new int[ranges.length];
        for (int index = 0; index < ranges.length; index++) {
            int low = ranges[index][0];
            int high = ranges[index][1];
            // low 이상이 처음 나오는 위치부터 high보다 큰 값이 처음 나오는 위치 앞까지가 구간 안의 점수다.
            answer[index] = upperBound(scores, high) - lowerBound(scores, low);
        }
        return answer;
    }

    // target 이상인 값이 처음 나오는 위치입니다. 모든 값이 작으면 배열 끝인 scores.length를 돌려줍니다.
    static int lowerBound(int[] scores, int target) {
        int lo = 0;
        int hi = scores.length;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (scores[mid] < target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }

    // target보다 큰 값이 처음 나오는 위치입니다. target과 같은 값은 왼쪽에 남겨야 하므로 <=로 비교합니다.
    static int upperBound(int[] scores, int target) {
        int lo = 0;
        int hi = scores.length;
        while (lo < hi) {
            int mid = lo + (hi - lo) / 2;
            if (scores[mid] <= target) lo = mid + 1;
            else hi = mid;
        }
        return lo;
    }
}

