import java.util.ArrayList;
import java.util.List;
import java.util.PriorityQueue;

public class Solution {
    public static int[] solve(int n, int[][] prerequisites) {
        // next.get(a)는 a가 끝나야 시작할 수 있는 작업 목록이고 inDegree[b]는 b 전에 끝나야 하는 작업 수다.
        List<List<Integer>> next = new ArrayList<>();
        for (int task = 0; task < n; task++) next.add(new ArrayList<>());
        int[] inDegree = new int[n];
        for (int[] rule : prerequisites) {
            next.get(rule[0]).add(rule[1]);
            inDegree[rule[1]]++;
        }

        // 지금 시작할 수 있는 작업이 여러 개이면 번호가 작은 작업부터 꺼내야 하므로
        // 넣은 순서대로 꺼내는 큐 대신 가장 작은 값을 먼저 꺼내는 PriorityQueue를 쓴다.
        PriorityQueue<Integer> ready = new PriorityQueue<>();
        for (int task = 0; task < n; task++) {
            if (inDegree[task] == 0) ready.add(task);
        }

        int[] order = new int[n];
        int count = 0;
        while (!ready.isEmpty()) {
            int now = ready.poll();
            order[count++] = now;
            for (int after : next.get(now)) {
                inDegree[after]--;
                if (inDegree[after] == 0) ready.add(after);
            }
        }

        // 사이클 안의 작업은 진입 차수가 0이 되지 않아 꺼내지지 못하므로 꺼낸 수가 n보다 적다.
        if (count < n) return new int[0];
        return order;
    }
}

