import java.util.ArrayList;
import java.util.List;

public class Solution {
    public static String[] solve(String script) {
        // 파싱: |는 정규식에서 "또는"을 뜻하므로 \\|로 적어야 글자 그대로의 막대로 나뉜다.
        String[] pieces = script.split("\\|");

        // 적용: 여러 번 고칠 전광판은 String 대신 StringBuilder 하나에 담아 그 자리에서 바꾼다.
        StringBuilder board = new StringBuilder();
        List<String> shown = new ArrayList<>();
        for (String piece : pieces) {
            String command = piece.trim();
            // 막대가 연달아 오거나 공백만 있는 조각은 명령이 아니므로 건너뛴다.
            if (command.isEmpty()) continue;

            // 이름과 인자 사이 공백이 여러 칸일 수 있어 "공백 한 칸 이상"을 구분자로 쓴다.
            String[] parts = command.split(" +");
            switch (parts[0]) {
                case "ADD" -> board.append(parts[1]);
                case "CUT" -> {
                    int count = Integer.parseInt(parts[1]);
                    // 지울 글자가 현재 글자 수보다 많으면 0글자까지만 줄인다.
                    board.setLength(Math.max(0, board.length() - count));
                }
                case "FLIP" -> board.reverse();
                // SHOW 시점의 내용을 새 String으로 꺼내 두어야 뒤 명령이 기록을 바꾸지 않는다.
                case "SHOW" -> shown.add(board.toString());
                default -> throw new IllegalArgumentException("알 수 없는 명령: " + parts[0]);
            }
        }
        return shown.toArray(new String[0]);
    }
}

