public class Solution {
    private static final int LIMIT = 1_000_000;

    public static int[] solve(int[][] queries) {
        // 구간 질의가 많으므로 한 수씩 판별하지 않고 체를 한 번만 만든다.
        // 번호가 곧 수가 되도록 크기를 LIMIT + 1로 두고 0과 1은 소수가 아니므로 먼저 지운다.
        boolean[] composite = new boolean[LIMIT + 1];
        composite[0] = true;
        composite[1] = true;
        for (int i = 2; (long) i * i <= LIMIT; i++) {
            if (composite[i]) continue;
            // i보다 작은 수를 곱한 배수는 앞에서 지웠으므로 i * i부터 지운다.
            for (int j = i * i; j <= LIMIT; j += i) {
                composite[j] = true;
            }
        }

        // primeCount[x]는 x 이하의 소수 개수다. 질의마다 두 값의 차이로 바로 답한다.
        int[] primeCount = new int[LIMIT + 1];
        for (int x = 1; x <= LIMIT; x++) {
            primeCount[x] = primeCount[x - 1] + (composite[x] ? 0 : 1);
        }

        int[] answer = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int lo = queries[i][0];
            int hi = queries[i][1];
            // lo도 구간에 들어가므로 lo - 1 이하의 개수를 뺀다.
            answer[i] = primeCount[hi] - primeCount[lo - 1];
        }
        return answer;
    }
}

