public class Solution {
    private static final int MOD = 1_000_000_007;
    private static final int MAX_N = 1_000;

    public static int[] solve(int[][] queries) {
        // 파스칼의 삼각형: nCr = (n-1)C(r-1) + (n-1)Cr을 윗줄부터 덧셈으로 채운다.
        // 표를 한 번만 만들면 질의마다 칸 하나를 읽어 바로 답한다.
        // 칸은 r > n인 자리까지 만들어 두면 채우지 않은 칸이 0이라 뽑을 수 없는 경우의 답이 된다.
        long[][] choose = new long[MAX_N + 1][MAX_N + 1];
        for (int n = 0; n <= MAX_N; n++) {
            choose[n][0] = 1;
            choose[n][n] = 1;
            for (int r = 1; r < n; r++) {
                // 덧셈은 중간에 나머지를 구해도 결과가 같으므로 칸마다 나머지만 남겨 넘치지 않게 한다.
                choose[n][r] = (choose[n - 1][r - 1] + choose[n - 1][r]) % MOD;
            }
        }

        int[] answer = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int n = queries[i][0];
            int r = queries[i][1];
            answer[i] = (int) choose[n][r];
        }
        return answer;
    }
}

