public class Solution {
    public static int solve(int[][] triangle, int[][] points) {
        int count = 0;
        for (int[] point : points) {
            // 세 변을 차례로 따라 걸을 때 가게가 어느 쪽에 있는지 외적의 부호로 본다.
            long first = cross(triangle[0], triangle[1], point);
            long second = cross(triangle[1], triangle[2], point);
            long third = cross(triangle[2], triangle[0], point);
            // 안쪽이면 세 변 모두 같은 쪽에 있고 변 위이면 그 변의 외적이 0이다.
            // 꼭짓점이 반시계 방향이면 모두 0 이상이고 시계 방향이면 모두 0 이하이다.
            boolean noNegative = first >= 0 && second >= 0 && third >= 0;
            boolean noPositive = first <= 0 && second <= 0 && third <= 0;
            if (noNegative || noPositive) {
                count++;
            }
        }
        return count;
    }

    // a → b 벡터와 a → c 벡터의 외적이다. 차끼리 곱하면 int 범위를 넘으므로 곱하기 전에 long으로 바꾼다.
    private static long cross(int[] a, int[] b, int[] c) {
        long abX = (long) b[0] - a[0];
        long abY = (long) b[1] - a[1];
        long acX = (long) c[0] - a[0];
        long acY = (long) c[1] - a[1];
        return abX * acY - abY * acX;
    }
}

